async function saveOffline(r:Item){if(!r.assetId){setToast('التنزيل متاح للملفات المرفوعة إلى المنصة فقط');return}setBusy(true);try{if(navigator.storage?.persist)await navigator.storage.persist();const resp=await fetch('/api/media?id='+r.assetId);if(!resp.ok)throw new Error('تعذر الوصول إلى الملف');const blob=await resp.blob();const h=new Headers(resp.headers);h.set('x-offline-title',encodeURIComponent(r.title));const en=active.find((e:Item)=>e.course_id===r.courseId);const until=Math.min(Date.now()+(data?.settings.offlineHours||48)*3600000,(!data?.user.admin&&!r.free)?(en?.expires||Date.now()):Infinity);h.set('x-offline-until',String(until));h.set('Content-Length',String(blob.size));await (await caches.open('farmakon-downloads-v1')).put('/api/media?id='+r.assetId,new Response(blob,{headers:h}));setToast('تم الحفظ على هذا الجهاز. متاح لفترة محدودة دون اتصال.');await downloads()}catch(e){setToast((e as Error).message||'تعذر التنزيل، تحقق من المساحة')}finally{setBusy(false)}}
async function upload(file:File){if(!modal?.data.courseId){setToast('اختر كورسًا أولًا');return}if(file.size>4*1024*1024){setToast('الحد الحالي 4MB للملف. يمكنك إضافة رابط HTTPS لفيديو أكبر.');return}setBusy(true);try{const r=await fetch(`/api/media?courseId=${encodeURIComponent(modal.data.courseId)}&name=${encodeURIComponent(file.name)}`,{method:'POST',headers:{'Content-Type':file.type},body:file});const d:any=await r.json();if(!r.ok)throw new Error(d.error);setModal(m=>m?{...m,data:{...m.data,url:d.url,assetId:d.id,title:m.data.title||file.name}}:m);setToast('اكتمل الرفع. احفظ المحاضرة أو الملف لإضافته للمكتبة.')}catch(e){setToast((e as Error).message)}finally{setBusy(false)}}
const courses=(data?.course||[]).filter((c:Item)=>(adminMode||c.status==='published')&&(!search||(c.title+' '+c.description).includes(search))&&(stage==='الكل'||c.stage===stage));
